package com.yonlab.vision;
import android.content.Context;import android.graphics.Bitmap;
import java.util.*;import java.io.*;
/** Common COCO label-ID contract for original SSD and the actual YOLO26 graph. */
final class OneObjectEngine implements AutoCloseable {
 private final ObjectEngine baseline;private final OneOnnx onnx;private final OneYoloXEngine yolox;private final AddedObjectEngine added;private final List<String> labels=new ArrayList<>(),sparse=new ArrayList<>();
 OneObjectEngine(Context c,String id)throws Exception {OneModelPolicy.validate("detect",id,android.os.Build.VERSION.SDK_INT);if(AddedVisionModels.object(id)){baseline=null;onnx=null;yolox=null;added=new AddedObjectEngine(c,id);return;}added=null;if("yolox-nano".equals(id)){baseline=null;onnx=null;yolox=new OneYoloXEngine(c);return;}yolox=null;if("ssd-mobilenet-v1".equals(id)||"efficientdet-lite0".equals(id)){baseline=new ObjectEngine(c,"efficientdet-lite0".equals(id));onnx=null;}else{baseline=null;onnx=new OneOnnx(c,id);read(c,"one/models/coco80-labels.txt",labels);read(c,"models/labelmap.txt",sparse);if(labels.size()!=80)throw new IOException("COCO labels");}}
 static void read(Context c,String asset,List<String> out)throws IOException{try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getAssets().open(asset),"UTF-8"))){String s;while((s=r.readLine())!=null)out.add(s.trim());}}
 List<Observations.Detection> analyze(Bitmap image,float threshold)throws Exception {if(added!=null)return added.analyze(image,threshold);if(yolox!=null)return yolox.analyze(image,threshold);if(baseline!=null)return baseline.analyze(image,threshold);return onnx.run(image,result->{Object value=OneOnnx.value(result,"output0");if(!(value instanceof float[][][]))throw new IOException("YOLO output rank");float[][][] rows=(float[][][])value;if(rows.length!=1||rows[0].length!=300)throw new IOException("YOLO output shape");List<Observations.Detection> out=new ArrayList<>();for(float[] row:rows[0]){if(row.length!=6)throw new IOException("YOLO output width");boolean finite=true;for(float f:row)finite&=OneModelMath.finite(f);if(!finite||row[4]<threshold||row[4]>1||row[5]!=Math.rint(row[5]))continue;int id=(int)row[5];if(id<0||id>=labels.size()||row[2]<=row[0]||row[3]<=row[1])continue;float[] b=OneModelMath.unletterbox(row[0],row[1],row[2],row[3],image.getWidth(),image.getHeight(),640);if(b[2]<=b[0]||b[3]<=b[1])continue;String label=labels.get(id);int sparseId=sparse.indexOf(label)-1;out.add(new Observations.Detection(Math.max(0,sparseId),label,row[4],b[0],b[1],b[2],b[3]));}return out;});}
 public void close(){if(added!=null)added.close();if(yolox!=null)yolox.close();else if(baseline!=null)baseline.close();if(onnx!=null)onnx.close();}
}
